shellCommands.command:
cd /workspace
for h in "plain" "rsc" "prefetch" "segtree"; do
  case $h in
    plain) H=();;
    rsc) H=(-H 'RSC: 1');;
    prefetch) H=(-H 'RSC: 1' -H 'next-router-prefetch: 1');;
    segtree) H=(-H 'RSC: 1' -H 'next-router-prefetch: 1' -H 'next-router-segment-prefetch: /_tree');;
  esac
  echo "=== $h ==="
  curl -s -D- -o /dev/null "${H[@]}" "http://localhost:3124/projects/zzz-$h" | head -12
done
